Pengguna salah ketik "Belajar stat" dan ingin memperbaikinya tanpa menghapus lalu menambah ulang. Fitur **edit**: klik tombol ✎ (atau klik dua kali teks), tugas berubah menjadi input, **Enter** menyimpan, **Esc** membatalkan.

Mode edit hanya berlaku untuk **satu** tugas dan hanya dipakai `ItemTugas` itu sendiri. Jadi state-nya disimpan di `ItemTugas`:

```jsx
function ItemTugas({ tugas, onUbah }) {
  const [edit, setEdit] = useState(false);
  const [teks, setTeks] = useState(tugas.teks);
  // ...
}
```

Ibarat **mengoreksi kartu di papan**: kartunya dicabut sebentar, ditulis ulang, lalu ditempel lagi. Kartu lain tidak terganggu.

Di `App`, cukup satu fungsi baru:

```jsx
function ubah(id, teks) {
  setTugas(tugas.map((t) => (t.id === id ? { ...t, teks } : t)));
}
```

`{ ...t, teks }` adalah singkatan `{ ...t, teks: teks }`.

### Dua tampilan dalam satu komponen

```jsx
if (edit) {
  return (
    <li>
      <input value={teks} onChange={(e) => setTeks(e.target.value)}
        onKeyDown={handleKey} onBlur={simpan} autoFocus aria-label="Ubah tugas" />
    </li>
  );
}
return (
  <li>
    ...
    <span onDoubleClick={() => setEdit(true)}>{tugas.teks}</span>
    <button onClick={() => setEdit(true)} aria-label={`Ubah ${tugas.teks}`}>✎</button>
  </li>
);
```

| Bagian | Fungsi |
|---|---|
| `autoFocus` | kursor langsung di input saat mode edit dibuka |
| `onKeyDown` | `Enter` menyimpan, `Escape` membatalkan |
| `onBlur` | menyimpan saat pengguna mengetuk di luar input (penting di HP) |
| tombol ✎ | cara edit yang terlihat; klik dua kali tidak nyaman di HP |

```jsx
function simpan() {
  const bersih = teks.trim();
  if (bersih !== '') onUbah(tugas.id, bersih);
  else setTeks(tugas.teks);  // isian kosong: kembalikan teks lama
  setEdit(false);
}
```

cards.code:
import { useState } from 'react';

const awal = [
  { id: 1, teks: 'Belajar JSX', selesai: true },
  { id: 2, teks: 'Belajar state', selesai: false },
  { id: 3, teks: 'Membuat todolist', selesai: false },
];

function FormTambah({ onTambah }) {
  const [teks, setTeks] = useState('');

  function handleSubmit(e) {
    e.preventDefault();
    const bersih = teks.trim();
    if (bersih === '') return;
    onTambah(bersih);
    setTeks('');
  }

  return (
    <form className="baris" onSubmit={handleSubmit}>
      <input type="text" value={teks} onChange={(e) => setTeks(e.target.value)} placeholder="Tugas baru" />
      <button type="submit">Tambah</button>
    </form>
  );
}

function ItemTugas({ tugas, onCentang, onHapus, onUbah }) {
  const [edit, setEdit] = useState(false);
  const [teks, setTeks] = useState(tugas.teks);

  function simpan() {
    const bersih = teks.trim();
    if (bersih !== '') onUbah(tugas.id, bersih);
    else setTeks(tugas.teks);
    setEdit(false);
  }

  function handleKey(e) {
    if (e.key === 'Enter') simpan();
    if (e.key === 'Escape') {
      setTeks(tugas.teks);
      setEdit(false);
    }
  }

  if (edit) {
    return (
      <li>
        <input type="text" value={teks} onChange={(e) => setTeks(e.target.value)}
          onKeyDown={handleKey} onBlur={simpan} autoFocus aria-label="Ubah tugas" />
      </li>
    );
  }

  return (
    <li className={tugas.selesai ? 'selesai' : ''}>
      <input type="checkbox" checked={tugas.selesai} onChange={() => onCentang(tugas.id)}
        aria-label={`Tandai ${tugas.teks} selesai`} />
      <span onDoubleClick={() => setEdit(true)}>{tugas.teks}</span>
      <button onClick={() => setEdit(true)} aria-label={`Ubah ${tugas.teks}`}>✎</button>
      <button onClick={() => onHapus(tugas.id)} aria-label={`Hapus ${tugas.teks}`}>✕</button>
    </li>
  );
}

export default function App() {
  const [tugas, setTugas] = useState(awal);

  function tambah(teks) {
    setTugas([...tugas, { id: crypto.randomUUID(), teks, selesai: false }]);
  }
  function centang(id) {
    setTugas(tugas.map((t) => (t.id === id ? { ...t, selesai: !t.selesai } : t)));
  }
  function hapus(id) {
    setTugas(tugas.filter((t) => t.id !== id));
  }
  function ubah(id, teks) {
    setTugas(tugas.map((t) => (t.id === id ? { ...t, teks } : t)));
  }

  return (
    <div className="todo">
      <h1>Todolist</h1>
      <FormTambah onTambah={tambah} />
      <ul className="daftar">
        {tugas.map((t) => (
          <ItemTugas key={t.id} tugas={t} onCentang={centang} onHapus={hapus} onUbah={ubah} />
        ))}
      </ul>
      <p className="kecil">Klik ✎ atau klik dua kali teks untuk mengubah. Enter menyimpan, Esc membatalkan.</p>
    </div>
  );
}

